-- 1. Ensure Columns for Prescription (อายุความตัวการ / อายุความผู้สนับสนุน) exist
ALTER TABLE IF EXISTS public.tbl_res_offense_basis
  ADD COLUMN IF NOT EXISTS trob_prescription_years_principal integer DEFAULT 20,
  ADD COLUMN IF NOT EXISTS trob_prescription_years_accessory integer DEFAULT 20,
  ADD COLUMN IF NOT EXISTS p_principal integer DEFAULT 20,
  ADD COLUMN IF NOT EXISTS p_accessory integer DEFAULT 20;

-- 1.1 Document the prescription columns directly on the table
COMMENT ON COLUMN public.tbl_res_offense_basis.trob_prescription_years_principal IS
  'อายุความคดีอาญาของฐานความผิดนี้สำหรับตัวการ (ผู้กระทำผิดหลัก) หน่วยเป็นปี คำนวณจากอัตราโทษสูงสุดของฐานความผิดตามประมวลกฎหมายอาญา มาตรา 95 (เช่น จำคุกตลอดชีวิตหรือ 20 ปี = อายุความ 20 ปี, จำคุกเกิน 7-20 ปี = 15 ปี, จำคุกเกิน 1-7 ปี = 10 ปี, จำคุกเกิน 1 เดือน-1 ปี = 5 ปี)';
COMMENT ON COLUMN public.tbl_res_offense_basis.trob_prescription_years_accessory IS
  'อายุความคดีอาญาของฐานความผิดนี้สำหรับผู้สนับสนุน/ผู้ใช้ (ผู้กระทำผิดรอง) หน่วยเป็นปี คำนวณแบบเดียวกับตัวการแต่ใช้อัตราโทษของผู้สนับสนุนตามประมวลกฎหมายอาญา มาตรา 86 (ระวางโทษ 2 ใน 3 ของอัตราโทษตัวการ) จึงอาจได้อายุความสั้นกว่าตัวการในบางฐานความผิด';
COMMENT ON COLUMN public.tbl_res_offense_basis.p_principal IS
  'คอลัมน์อายุความตัวการแบบย่อ เก็บค่าเดียวกับ trob_prescription_years_principal (หน่วยเป็นปี) — เป็นชื่อฟิลด์ที่หน้าจอจัดทำรายงานวินิจฉัยชี้มูล (ruling-report.html) เรียกใช้จริงเพื่อคำนวณวันขาดอายุความของผู้ถูกกล่าวหาแต่ละรายเมื่อมีบทบาทเป็นตัวการ';
COMMENT ON COLUMN public.tbl_res_offense_basis.p_accessory IS
  'คอลัมน์อายุความผู้สนับสนุนแบบย่อ เก็บค่าเดียวกับ trob_prescription_years_accessory (หน่วยเป็นปี) — เป็นชื่อฟิลด์ที่หน้าจอจัดทำรายงานวินิจฉัยชี้มูล (ruling-report.html) เรียกใช้จริงเพื่อคำนวณวันขาดอายุความของผู้ถูกกล่าวหาแต่ละรายเมื่อมีบทบาทเป็นผู้สนับสนุน/ผู้ใช้';

-- 2. Clean old rows or insert full 49 items
TRUNCATE TABLE public.tbl_res_offense_basis RESTART IDENTITY CASCADE;

INSERT INTO public.tbl_res_offense_basis (
  trob_group, trob_law_name, trob_article_no, trob_article_label,
  trob_prescription_years_principal, trob_prescription_years_accessory,
  p_principal, p_accessory, trob_sort_order, is_deleted
) VALUES
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๔๗', 'เจ้าพนักงานยักยอกทรัพย์', 20, 20, 20, 20, 1, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๔๘', 'เจ้าพนักงานกรรโชกทรัพย์', 20, 20, 20, 20, 2, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๔๙', 'เจ้าพนักงานเรียก รับ หรือยอมจะรับสินบน', 20, 20, 20, 20, 3, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๕๐', 'เจ้าพนักงานกระทำการหรือไม่กระทำการอย่างใดโดยเห็นแก่ทรัพย์สินซึ่งเรียกหรือรับไว้ก่อนได้รับแต่งตั้งในตำแหน่งนั้น', 20, 20, 20, 20, 4, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๕๑', 'เจ้าพนักงานใช้อำนาจในตำแหน่งโดยทุจริต จัดการทรัพย์ อันเป็นการเสียหาย', 20, 20, 20, 20, 5, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๕๒', 'เจ้าพนักงานมีส่วนได้เสียเนื่องด้วยกิจการที่ตนมีหน้าที่จัดการหรือดูแล', 15, 10, 15, 10, 6, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๕๓', 'เจ้าพนักงานจ่ายทรัพย์เกินกว่าที่ควรจ่าย', 15, 10, 15, 10, 7, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๕๔', 'เจ้าพนักงานเรียกเก็บหรือไม่เรียกเก็บภาษี/ค่าธรรมเนียม/เงินอื่นใดโดยทุจริต หรือโดยทุจริตกระทำหรือไม่กระทำการอย่างใดเพื่อให้ผู้มีหน้าที่ไม่ต้องเสียหรือเสียน้อย', 20, 20, 20, 20, 8, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๕๕', 'เจ้าพนักงานโดยทุจริตกำหนดราคาทรัพย์สินหรือสินค้าเพื่อให้ผู้ต้องเสียภาษี หรือค่าธรรมเนียมไม่ต้องเสียหรือเสียน้อย', 20, 20, 20, 20, 9, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๕๖', 'เจ้าพนักงานโดยทุจริตแนะนำเกี่ยวกับการลงบัญชี ทำให้มิต้องเสียภาษีหรือค่าธรรมเนียม หรือเสียน้อย', 20, 20, 20, 20, 10, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๕๗', 'เจ้าพนักงานปฏิบัติหรือละเว้นการปฏิบัติหน้าที่โดยมิชอบเพื่อให้เกิดความเสียหายแก่ผู้หนึ่งผู้ใดหรือปฏิบัติหรือละเว้นการปฏิบัติหน้าที่โดยทุจริต', 15, 10, 15, 10, 11, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๕๘', 'เจ้าพนักงานทำให้เสียหาย ซ่อนเร้น เอาไปเสียซึ่งทรัพย์หรือเอกสาร ซึ่งตนมีหน้าที่ปกครองหรือรักษา', 10, 10, 10, 10, 12, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๕๙', 'เจ้าพนักงานถอน ทำให้เสียหาย ซึ่งตราหรือเครื่องหมาย อันเจ้าพนักงานได้ประทับไว้ที่ทรัพย์หรือเอกสารเพื่อเป็นหลักฐานในการยึดหรือรักษาสิ่งนั้น', 10, 10, 10, 10, 13, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๖๐', 'เจ้าพนักงานใช้ดวงตราหรือรอยตราอันมิชอบด้วยหน้าที่ซึ่งทำให้ผู้อื่นเสียหาย', 10, 10, 10, 10, 14, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๖๑', 'เจ้าพนักงานปลอมเอกสาร', 15, 10, 15, 10, 15, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๖๒', 'เจ้าพนักงานทำเอกสารเท็จ', 10, 10, 10, 10, 16, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๖๓', 'เจ้าพนักงานทำให้เสียหายซึ่งจดหมายหรือสิ่งอื่นที่ส่งทางไปรษณีย์ หรือโทรเลข', 10, 10, 10, 10, 17, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๖๔', 'เจ้าพนักงานเปิดเผยความลับ', 10, 10, 10, 10, 18, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๖๕', 'เจ้าพนักงานป้องกันหรือขัดขวางมิให้การเป็นไปตามกฎหมายหรือคำสั่ง', 5, 5, 5, 5, 19, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๖๖ ว.๑', 'เจ้าพนักงานละทิ้งงาน หรือกระทำการใด ๆ เพื่อให้งานเสียหาย', 10, 10, 10, 10, 20, false),
  ('๑. ประมวลกฎหมายอาญา หมวดความผิดต่อตำแหน่งหน้าที่ราชการ', 'ประมวลกฎหมายอาญา', 'มาตรา ๑๖๖ ว.๒', 'เพื่อให้เกิดการเปลี่ยนแปลงกฎหมาย บังคับรัฐบาล ข่มขู่ประชาชน', 15, 10, 15, 10, 21, false),
  ('หมวดความผิดต่อตำแหน่งหน้าที่ในการยุติธรรม (ป.อาญา)', 'ประมวลกฎหมายอาญา', 'มาตรา ๒๐๐ ว.๑', 'เจ้าพนักงานในการยุติธรรมกระทำหรือไม่กระทำการในตำแหน่งเพื่อจะช่วยบุคคลใดมิให้ต้องโทษ หรือได้รับโทษน้อยลง', 10, 10, 10, 10, 22, false),
  ('หมวดความผิดต่อตำแหน่งหน้าที่ในการยุติธรรม (ป.อาญา)', 'ประมวลกฎหมายอาญา', 'มาตรา ๒๐๐ ว.๒', 'เพื่อจะแกล้งบุคคลใดให้ต้องรับโทษหรือรับโทษหนักขึ้น', 20, 20, 20, 20, 23, false),
  ('หมวดความผิดต่อตำแหน่งหน้าที่ในการยุติธรรม (ป.อาญา)', 'ประมวลกฎหมายอาญา', 'มาตรา ๒๐๑', 'เจ้าพนักงานในการยุติธรรมรับสินบน', 20, 20, 20, 20, 24, false),
  ('หมวดความผิดต่อตำแหน่งหน้าที่ในการยุติธรรม (ป.อาญา)', 'ประมวลกฎหมายอาญา', 'มาตรา ๒๐๒', 'เจ้าพนักงานในการยุติธรรมกระทำหรือไม่กระทำการอย่างใดโดยเห็นแก่ทรัพย์สินซึ่งได้เรียก/รับไว้ก่อนได้รับแต่งตั้งในตำแหน่งนั้น', 20, 20, 20, 20, 25, false),
  ('หมวดความผิดต่อตำแหน่งหน้าที่ในการยุติธรรม (ป.อาญา)', 'ประมวลกฎหมายอาญา', 'มาตรา ๒๐๓', 'เจ้าพนักงานป้องกันหรือขัดขวางมิให้การเป็นไปตามคำพิพากษาหรือคำสั่งของศาล', 10, 10, 10, 10, 26, false),
  ('หมวดความผิดต่อตำแหน่งหน้าที่ในการยุติธรรม (ป.อาญา)', 'ประมวลกฎหมายอาญา', 'มาตรา ๒๐๔ ว.๑', 'เจ้าพนักงานผู้ควบคุมผู้ต้องขัง ทำให้ผู้ต้องขังหลุดพ้นจากการคุมขัง', 10, 10, 10, 10, 27, false),
  ('หมวดความผิดต่อตำแหน่งหน้าที่ในการยุติธรรม (ป.อาญา)', 'ประมวลกฎหมายอาญา', 'มาตรา ๒๐๔ ว.๒', 'ผู้หลุดพ้นจากการคุมขังโทษหนัก หรือ ๓ คน ขึ้นไป', 15, 10, 15, 10, 28, false),
  ('หมวดความผิดต่อตำแหน่งหน้าที่ในการยุติธรรม (ป.อาญา)', 'ประมวลกฎหมายอาญา', 'มาตรา ๒๐๕ ว.๑', 'เจ้าพนักงานทำให้ผู้ต้องขังหลุดพ้นจากการคุมขังโดยประมาท', 10, 10, 10, 10, 29, false),
  ('หมวดความผิดต่อตำแหน่งหน้าที่ในการยุติธรรม (ป.อาญา)', 'ประมวลกฎหมายอาญา', 'มาตรา ๒๐๕ ว.๒', 'ผู้หลุดพ้นจากการคุมขังโทษหนัก หรือ ๓ คน ขึ้นไป (โดยประมาท)', 10, 10, 10, 10, 30, false),
  ('๒. พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'มาตรา ๔', 'พนักงานยักยอกทรัพย์', 20, 20, 20, 20, 31, false),
  ('๒. พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'มาตรา ๕', 'พนักงานใช้อำนาจหน้าที่โดยมิชอบ ข่มขืนใจผู้อื่นให้มอบทรัพย์สิน หรือประโยชน์อื่นใดแก่ตนหรือผู้อื่น', 20, 20, 20, 20, 32, false),
  ('๒. พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'มาตรา ๖', 'พนักงานเรียกรับหรือรับสินบน', 20, 20, 20, 20, 33, false),
  ('๒. พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'มาตรา ๗', 'พนักงานกระทำการหรือไม่กระทำการอย่างใดโดยเห็นแก่ทรัพย์สินซึ่งได้เรียกหรือรับไว้ก่อนได้รับแต่งตั้งเป็นพนักงานในหน้าที่นั้น', 20, 20, 20, 20, 34, false),
  ('๒. พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'มาตรา ๘', 'พนักงานใช้อำนาจในหน้าที่โดยทุจริต จัดการทรัพย์อันเป็นการเสียหาย', 20, 20, 20, 20, 35, false),
  ('๒. พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'มาตรา ๙', 'พนักงานมีส่วนได้เสียเนื่องด้วยกิจการที่ตนมีหน้าที่จัดการ หรือดูแล', 15, 10, 15, 10, 36, false),
  ('๒. พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'มาตรา ๑๐', 'พนักงานจ่ายทรัพย์เกิน เพื่อประโยชน์ของตนเองหรือผู้อื่น', 15, 10, 15, 10, 37, false),
  ('๒. พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'พ.ร.บ. ว่าด้วยความผิดของพนักงานในองค์การหรือหน่วยงานของรัฐ พ.ศ. ๒๕๐๒', 'มาตรา ๑๑', 'พนักงานปฏิบัติหรือละเว้นการปฏิบัติหน้าที่โดยมิชอบเพื่อให้เกิดความเสียหายแก่ผู้หนึ่งผู้ใดหรือปฏิบัติหรือละเว้นการปฏิบัติหน้าที่โดยทุจริต', 15, 10, 15, 10, 38, false),
  ('๓. พ.ร.ป. ป.ป.ช. พ.ศ. ๒๕๔๒ (และแก้ไขเพิ่มเติม ฉบับ ๒, ๓)', 'พ.ร.บ. ประกอบรัฐธรรมนูญว่าด้วยการป้องกันและปราบปรามการทุจริต พ.ศ. ๒๕๔๒', 'มาตรา ๑๒๓ (๔๒)', 'เจ้าหน้าที่ของรัฐปฏิบัติหรือละเว้นการปฏิบัติอย่างใด เพื่อให้ผู้อื่นเชื่อว่ามีตำแหน่งหน้าที่ เพื่อแสวงหาประโยชน์ที่มิควรได้ (ใช้บังคับ ๑๘ พ.ย. ๒๕๔๒ ถึง ๒๑ ก.ค. ๒๕๖๑)', 15, 10, 15, 10, 39, false),
  ('๓. พ.ร.ป. ป.ป.ช. พ.ศ. ๒๕๔๒ (และแก้ไขเพิ่มเติม ฉบับ ๒, ๓)', 'พ.ร.บ. ประกอบรัฐธรรมนูญว่าด้วยการป้องกันและปราบปรามการทุจริต พ.ศ. ๒๕๔๒', 'มาตรา ๑๒๓/๑ (๔๒)', 'เจ้าหน้าที่ของรัฐปฏิบัติหรือละเว้นการปฏิบัติหน้าที่หรือใช้อำนาจในตำแหน่งหน้าที่โดยมิชอบเพื่อให้เกิดความเสียหายแก่ผู้หนึ่งผู้ใดหรือปฏิบัติหรือละเว้นการปฏิบัติหน้าที่โดยทุจริต (ใช้บังคับ ๑๙ เม.ย. ๒๕๕๔ ถึง ๒๑ ก.ค. ๒๕๖๑)', 15, 10, 15, 10, 40, false),
  ('๓. พ.ร.ป. ป.ป.ช. พ.ศ. ๒๕๔๒ (และแก้ไขเพิ่มเติม ฉบับ ๒, ๓)', 'พ.ร.บ. ประกอบรัฐธรรมนูญว่าด้วยการป้องกันและปราบปรามการทุจริต พ.ศ. ๒๕๔๒', 'มาตรา ๑๒๓/๒ (๔๒)', 'เจ้าหน้าที่ของรัฐเรียกรับสินบน (ใช้บังคับ ๑๐ ก.ค. ๒๕๕๘ ถึง ๒๑ ก.ค. ๒๕๖๑)', 20, 20, 20, 20, 41, false),
  ('๓. พ.ร.ป. ป.ป.ช. พ.ศ. ๒๕๔๒ (และแก้ไขเพิ่มเติม ฉบับ ๒, ๓)', 'พ.ร.บ. ประกอบรัฐธรรมนูญว่าด้วยการป้องกันและปราบปรามการทุจริต พ.ศ. ๒๕๔๒', 'มาตรา ๑๒๓/๓ (๔๒)', 'เจ้าหน้าที่ของรัฐปฏิบัติหน้าที่ไม่ชอบโดยเห็นแก่รับสินบนที่เรียกรับ ก่อนรับตำแหน่ง (ใช้บังคับ ๑๐ ก.ค. ๒๕๕๘ ถึง ๒๑ ก.ค. ๒๕๖๑)', 20, 20, 20, 20, 42, false),
  ('๔. พ.ร.ป. ป.ป.ช. พ.ศ. ๒๕๖๑ (บังคับใช้ ๒๒ ก.ค. ๒๕๖๑ เป็นต้นไป)', 'พ.ร.บ. ประกอบรัฐธรรมนูญว่าด้วยการป้องกันและปราบปรามการทุจริต พ.ศ. ๒๕๖๑', 'มาตรา ๑๗๑ (๖๑)', 'เจ้าพนักงานของรัฐปฏิบัติหรือละเว้นการปฏิบัติอย่างใด เพื่อให้ผู้อื่นเชื่อว่ามีตำแหน่งหน้าที่ เพื่อแสวงหาประโยชน์ที่มิควรได้', 15, 10, 15, 10, 43, false),
  ('๔. พ.ร.ป. ป.ป.ช. พ.ศ. ๒๕๖๑ (บังคับใช้ ๒๒ ก.ค. ๒๕๖๑ เป็นต้นไป)', 'พ.ร.บ. ประกอบรัฐธรรมนูญว่าด้วยการป้องกันและปราบปรามการทุจริต พ.ศ. ๒๕๖๑', 'มาตรา ๑๗๒ (๖๑)', 'เจ้าพนักงานของรัฐปฏิบัติหรือละเว้นการปฏิบัติหน้าที่หรือใช้อำนาจในตำแหน่งหน้าที่โดยมิชอบเพื่อให้เกิดความเสียหายแก่ผู้หนึ่งผู้ใดหรือปฏิบัติหรือละเว้นการปฏิบัติหน้าที่โดยทุจริต', 15, 10, 15, 10, 44, false),
  ('๔. พ.ร.ป. ป.ป.ช. พ.ศ. ๒๕๖๑ (บังคับใช้ ๒๒ ก.ค. ๒๕๖๑ เป็นต้นไป)', 'พ.ร.บ. ประกอบรัฐธรรมนูญว่าด้วยการป้องกันและปราบปรามการทุจริต พ.ศ. ๒๕๖๑', 'มาตรา ๑๗๓ (๖๑)', 'เจ้าพนักงานของรัฐเรียกรับสินบน', 20, 20, 20, 20, 45, false),
  ('๔. พ.ร.ป. ป.ป.ช. พ.ศ. ๒๕๖๑ (บังคับใช้ ๒๒ ก.ค. ๒๕๖๑ เป็นต้นไป)', 'พ.ร.บ. ประกอบรัฐธรรมนูญว่าด้วยการป้องกันและปราบปรามการทุจริต พ.ศ. ๒๕๖๑', 'มาตรา ๑๗๔ (๖๑)', 'เจ้าพนักงานของรัฐปฏิบัติหน้าที่ไม่ชอบโดยเห็นแก่รับสินบนที่เรียกรับ ก่อนรับตำแหน่ง', 20, 20, 20, 20, 46, false),
  ('๕. พ.ร.บ. จัดซื้อจัดจ้างฯ ๒๕๖๐ และ ฮั้วประมูล ๒๕๔๒', 'พ.ร.บ. การจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐', 'มาตรา ๑๒๐', 'ผู้มีหน้าที่ปฏิบัติการจัดซื้อจัดจ้างปฏิบัติหรือละเว้นการปฏิบัติโดยมิชอบ', 15, 10, 15, 10, 47, false),
  ('๕. พ.ร.บ. จัดซื้อจัดจ้างฯ ๒๕๖๐ และ ฮั้วประมูล ๒๕๔๒', 'พ.ร.บ. ว่าด้วยความผิดเกี่ยวกับการเสนอราคาต่อหน่วยงานของรัฐ พ.ศ. ๒๕๔๒', 'มาตรา ๑๐', 'เจ้าหน้าที่ใช้อำนาจเอื้อประโยชน์ในการเสนอราคา', 20, 20, 20, 20, 48, false),
  ('๕. พ.ร.บ. จัดซื้อจัดจ้างฯ ๒๕๖๐ และ ฮั้วประมูล ๒๕๔๒', 'พ.ร.บ. ว่าด้วยความผิดเกี่ยวกับการเสนอราคาต่อหน่วยงานของรัฐ พ.ศ. ๒๕๔๒', 'มาตรา ๑๒', 'เจ้าหน้าที่ละเว้นมิให้มีการแข่งขันราคาอย่างเป็นธรรม', 20, 15, 20, 15, 49, false);
